package com.gymmind.workout.api;
import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.*; import com.gymmind.workout.application.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/training") public class TrainingController { private final TrainingOverviewService service; private final TrainingPlanService plans; private final CurrentActorProvider actors; public TrainingController(TrainingOverviewService s,TrainingPlanService p,CurrentActorProvider a){service=s;plans=p;actors=a;} @GetMapping("/overview") public ApiResponse<TrainingOverviewView> overview(@RequestParam(required=false) LocalDate since,@RequestParam(required=false) LocalDate until,@RequestParam(required=false) Long memberId){return ApiResponse.success(service.overview(actors.requireCurrent(),since,until,memberId));} @GetMapping("/records") public ApiResponse<TrainingOverviewView> records(@RequestParam(required=false) LocalDate since,@RequestParam(required=false) LocalDate until,@RequestParam(required=false) Long memberId){return overview(since,until,memberId);} @GetMapping("/plans") public ApiResponse<?> templates(){return ApiResponse.success(plans.templates(actors.requireCurrent()));} @GetMapping("/plans/{id}") public ApiResponse<?> template(@PathVariable Long id){return ApiResponse.success(plans.template(actors.requireCurrent(),id));} @PostMapping("/plans") public ApiResponse<?> create(@RequestBody CreateTemplateCommand c){return ApiResponse.success(plans.create(actors.requireCurrent(),c));} @PostMapping("/plans/{id}/publish") public ApiResponse<?> publish(@PathVariable Long id){return ApiResponse.success(plans.publish(actors.requireCurrent(),id));} @PostMapping("/member-plans") public ApiResponse<?> select(@RequestParam Long templateId){return ApiResponse.success(plans.select(actors.requireCurrent(),templateId));} @GetMapping("/member-plans") public ApiResponse<?> memberPlans(){return ApiResponse.success(plans.memberPlans(actors.requireCurrent()));} @GetMapping("/calendar") public ApiResponse<?> calendar(@RequestParam LocalDate from,@RequestParam LocalDate to){return ApiResponse.success(plans.calendar(actors.requireCurrent(),from,to));} @PostMapping("/calendar/schedules") public ApiResponse<?> schedule(@RequestParam Long memberPlanId,@RequestParam LocalDate date){return ApiResponse.success(plans.schedule(actors.requireCurrent(),memberPlanId,date));} @DeleteMapping("/calendar/schedules/{id}") public ApiResponse<?> deleteSchedule(@PathVariable Long id){plans.deleteSchedule(actors.requireCurrent(),id);return ApiResponse.success(null);} }
